//! SoulWorker 2.3.34.7 (GB / Steam) TCP framing, body crypto and a Tokio codec.
//!
//! Every rule here comes from SoulWorker64.dll 2.3.34.7 (sha256 cbe04466…,
//! Ghidra image base 0x180000000), read with REA/Ghidra and then checked by
//! running the client's own routines under Unicorn (`swemu/re/emu_wire.py`).
//! `tables.rs` and `golden.rs` are generated by that script from the DLL.
//!
//! ```text
//! Header, 11 bytes, little-endian, always cleartext
//!   [0..2]  u16 magic   0x0033                pktinit FUN_18005b5f0 `mov dword [rcx], 0x33`
//!   [2..4]  u16 size    header + body          FUN_18005b680/700/7e0 `size = body_len + 0xb`
//!   [4]     u8  flag    client always sends 1  FUN_1805ef010; not checked on receive
//!   [5]     u8  key     rolling u8 counter     FUN_18005c680 `++key`; row = key & 0x0F
//!   [6]     u8  mode    0 plain, 1 XOR, 3 AES-128-CTR (FUN_18005d170 dispatch)
//!   [7..11] u32 seq     per-connection counter FUN_18005c680 `++seq` (first packet = 1)
//! Body, size - 11 bytes, encrypted as one unit when mode != 0
//!   [0] main  [1] sub  [2] pad (0..=7)  [3 .. 3+pad] filler  [3+pad ..] payload
//! ```
//!
//! Receive-side rules mirrored from the client (FUN_18005d1c0, FUN_1805efa90):
//! a plaintext frame is refused once the peer has switched to an encrypted mode,
//! and a pad byte >= 8 makes the packet invalid.

pub mod crypto;
mod tables;

#[cfg(test)]
pub(crate) mod golden;

use bytes::{Buf, BufMut, Bytes, BytesMut};
use std::fmt;
use tokio_util::codec::{Decoder, Encoder};

pub const HEADER_LEN: usize = 11;
/// main + sub + pad-count.
pub const BODY_PREFIX_LEN: usize = 3;
pub const MIN_FRAME: usize = HEADER_LEN + BODY_PREFIX_LEN;
/// `size` is a u16 and the client's encoders refuse anything larger.
pub const MAX_FRAME: usize = u16::MAX as usize;
pub const MAGIC: u16 = 0x0033;
/// FUN_1805efa90 rejects `pad >= 8`; the client's own sender uses `rand() % 8`.
pub const MAX_PAD: u8 = 7;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum Mode {
    Plain = 0,
    Xor = 1,
    Aes = 3,
}

impl Mode {
    pub fn from_byte(b: u8) -> Option<Self> {
        match b {
            0 => Some(Self::Plain),
            1 => Some(Self::Xor),
            3 => Some(Self::Aes),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Header {
    pub magic: u16,
    pub size: u16,
    pub flag: u8,
    pub key: u8,
    /// Raw byte; use [`Mode::from_byte`].
    pub mode: u8,
    pub seq: u32,
}

impl Header {
    pub fn parse(b: &[u8; HEADER_LEN]) -> Self {
        Self {
            magic: u16::from_le_bytes([b[0], b[1]]),
            size: u16::from_le_bytes([b[2], b[3]]),
            flag: b[4],
            key: b[5],
            mode: b[6],
            seq: u32::from_le_bytes([b[7], b[8], b[9], b[10]]),
        }
    }

    pub fn to_bytes(&self) -> [u8; HEADER_LEN] {
        let mut b = [0u8; HEADER_LEN];
        b[0..2].copy_from_slice(&self.magic.to_le_bytes());
        b[2..4].copy_from_slice(&self.size.to_le_bytes());
        b[4] = self.flag;
        b[5] = self.key;
        b[6] = self.mode;
        b[7..11].copy_from_slice(&self.seq.to_le_bytes());
        b
    }
}

/// One decrypted, de-padded packet.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Packet {
    pub header: Header,
    pub main: u8,
    pub sub: u8,
    /// Number of filler bytes that were skipped.
    pub pad: u8,
    pub payload: Bytes,
}

impl Packet {
    pub fn opcode(&self) -> u16 {
        u16::from(self.main) << 8 | u16::from(self.sub)
    }
}

/// A packet queued for sending; header, padding and crypto are added by the codec.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Outgoing {
    pub main: u8,
    pub sub: u8,
    pub payload: Bytes,
}

impl Outgoing {
    pub fn new(main: u8, sub: u8, payload: impl Into<Bytes>) -> Self {
        Self { main, sub, payload: payload.into() }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SeqPolicy {
    /// Every frame must carry a larger `seq` than the previous one (drops replays).
    Increasing,
    /// Accept anything (useful for offline decoding of captures).
    Any,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SendPolicy {
    /// Must be `Xor` or `Aes` when talking to the real client: after its first
    /// encrypted send it refuses plaintext frames.
    pub mode: Mode,
    pub flag: u8,
    /// Insert `rand() % 8` filler bytes like the client's own sender.
    pub random_padding: bool,
}

impl Default for SendPolicy {
    fn default() -> Self {
        Self { mode: Mode::Xor, flag: 1, random_padding: false }
    }
}

#[derive(Debug)]
pub enum WireError {
    Io(std::io::Error),
    BadMagic(u16),
    Undersized(u16),
    Oversized { size: usize, max: usize },
    UnknownMode(u8),
    PlaintextAfterEncrypted,
    Replay { seq: u32, last: u32 },
    BadPadding(u8),
    PaddingOverrun { pad: u8, body_len: usize },
}

impl fmt::Display for WireError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(e) => write!(f, "i/o: {e}"),
            Self::BadMagic(m) => write!(f, "bad magic 0x{m:04X} (expected 0x{MAGIC:04X})"),
            Self::Undersized(s) => write!(f, "frame size {s} below minimum {MIN_FRAME}"),
            Self::Oversized { size, max } => write!(f, "frame size {size} above limit {max}"),
            Self::UnknownMode(m) => write!(f, "unknown crypto mode {m}"),
            Self::PlaintextAfterEncrypted => write!(f, "plaintext frame after the peer switched to encryption"),
            Self::Replay { seq, last } => write!(f, "sequence {seq} not after {last} (replay or reorder)"),
            Self::BadPadding(p) => write!(f, "pad count {p} > {MAX_PAD}"),
            Self::PaddingOverrun { pad, body_len } => write!(f, "pad count {pad} overruns body of {body_len} bytes"),
        }
    }
}

impl std::error::Error for WireError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Io(e) => Some(e),
            _ => None,
        }
    }
}

impl From<std::io::Error> for WireError {
    fn from(e: std::io::Error) -> Self {
        Self::Io(e)
    }
}

/// Stateful per-connection codec (one instance per TCP stream).
pub struct WireCodec {
    send: SendPolicy,
    send_key: u8,
    send_seq: u32,
    rng: u64,
    max_frame: usize,
    seq_policy: SeqPolicy,
    last_seq: Option<u32>,
    peer_encrypted: bool,
}

impl WireCodec {
    pub fn new(send: SendPolicy) -> Self {
        use std::hash::{BuildHasher, Hasher};
        // Non-cryptographic: padding only has to look like the client's rand().
        let seed = std::collections::hash_map::RandomState::new().build_hasher().finish() | 1;
        Self {
            send,
            send_key: 0,
            send_seq: 0,
            rng: seed,
            max_frame: MAX_FRAME,
            seq_policy: SeqPolicy::Increasing,
            last_seq: None,
            peer_encrypted: false,
        }
    }

    /// Lower the accepted incoming frame size (bounds per-connection buffering).
    pub fn with_max_frame(mut self, max: usize) -> Self {
        self.max_frame = max.clamp(MIN_FRAME, MAX_FRAME);
        self
    }

    pub fn with_seq_policy(mut self, p: SeqPolicy) -> Self {
        self.seq_policy = p;
        self
    }

    fn next_rand(&mut self) -> u64 {
        // xorshift64*
        let mut x = self.rng;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.rng = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    fn next_pad(&mut self) -> u8 {
        if self.send.random_padding { (self.next_rand() % (u64::from(MAX_PAD) + 1)) as u8 } else { 0 }
    }
}

impl Decoder for WireCodec {
    type Item = Packet;
    type Error = WireError;

    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Packet>, WireError> {
        if src.len() < HEADER_LEN {
            src.reserve(HEADER_LEN - src.len());
            return Ok(None);
        }
        let header = Header::parse(src[..HEADER_LEN].try_into().expect("length checked"));

        // Validate everything the header alone can tell us before buffering the body,
        // so a hostile size field cannot make us wait for (or allocate) junk.
        if header.magic != MAGIC {
            return Err(WireError::BadMagic(header.magic));
        }
        let size = usize::from(header.size);
        if size < MIN_FRAME {
            return Err(WireError::Undersized(header.size));
        }
        if size > self.max_frame {
            return Err(WireError::Oversized { size, max: self.max_frame });
        }
        let mode = Mode::from_byte(header.mode).ok_or(WireError::UnknownMode(header.mode))?;

        if src.len() < size {
            src.reserve(size - src.len());
            return Ok(None);
        }

        if mode == Mode::Plain && self.peer_encrypted {
            return Err(WireError::PlaintextAfterEncrypted);
        }
        if self.seq_policy == SeqPolicy::Increasing {
            if let Some(last) = self.last_seq {
                if header.seq <= last {
                    return Err(WireError::Replay { seq: header.seq, last });
                }
            }
        }

        let mut body = src.split_to(size).split_off(HEADER_LEN);
        crypto::apply(mode, &header, &mut body);

        let (main, sub, pad) = (body[0], body[1], body[2]);
        if pad > MAX_PAD {
            return Err(WireError::BadPadding(pad));
        }
        let payload_start = BODY_PREFIX_LEN + usize::from(pad);
        if payload_start > body.len() {
            return Err(WireError::PaddingOverrun { pad, body_len: body.len() });
        }
        body.advance(payload_start);

        self.last_seq = Some(header.seq);
        self.peer_encrypted |= mode != Mode::Plain;
        Ok(Some(Packet { header, main, sub, pad, payload: body.freeze() }))
    }
}

impl Encoder<Outgoing> for WireCodec {
    type Error = WireError;

    fn encode(&mut self, pkt: Outgoing, dst: &mut BytesMut) -> Result<(), WireError> {
        let pad = self.next_pad();
        let size = MIN_FRAME + usize::from(pad) + pkt.payload.len();
        if size > MAX_FRAME {
            return Err(WireError::Oversized { size, max: MAX_FRAME });
        }
        self.send_key = self.send_key.wrapping_add(1);
        self.send_seq = self.send_seq.wrapping_add(1);
        let header = Header {
            magic: MAGIC,
            size: size as u16,
            flag: self.send.flag,
            key: self.send_key,
            mode: self.send.mode as u8,
            seq: self.send_seq,
        };

        dst.reserve(size);
        let start = dst.len();
        dst.put_slice(&header.to_bytes());
        dst.put_u8(pkt.main);
        dst.put_u8(pkt.sub);
        dst.put_u8(pad);
        for _ in 0..pad {
            let b = self.next_rand() as u8;
            dst.put_u8(b);
        }
        dst.put_slice(&pkt.payload);
        crypto::apply(self.send.mode, &header, &mut dst[start + HEADER_LEN..]);
        Ok(())
    }
}

/// Build one wire frame from an explicit header and plaintext body
/// (`main | sub | pad | filler | payload`). Used by tests and tools.
pub fn seal(header: &Header, body: &[u8]) -> Vec<u8> {
    let mode = Mode::from_byte(header.mode).expect("seal: unknown mode");
    let mut out = Vec::with_capacity(HEADER_LEN + body.len());
    out.extend_from_slice(&header.to_bytes());
    out.extend_from_slice(body);
    crypto::apply(mode, header, &mut out[HEADER_LEN..]);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hex(s: &str) -> Vec<u8> {
        (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
    }

    fn any_seq() -> WireCodec {
        WireCodec::new(SendPolicy::default()).with_seq_policy(SeqPolicy::Any)
    }

    /// Our decoder inverts the client's encrypt routine, and our encryption
    /// reproduces the client's frames byte for byte (all modes, all 16 rows).
    #[test]
    fn golden_vectors_from_client() {
        assert!(golden::VECTORS.len() >= 38);
        for &(name, body_hex, wire_hex) in golden::VECTORS {
            let body = hex(body_hex);
            let wire = hex(wire_hex);

            let mut buf = BytesMut::from(&wire[..]);
            let pkt = any_seq().decode(&mut buf).unwrap().unwrap_or_else(|| panic!("{name}: incomplete"));
            assert!(buf.is_empty(), "{name}: leftover bytes");
            assert_eq!((pkt.main, pkt.sub, pkt.pad), (body[0], body[1], body[2]), "{name}");
            assert_eq!(&pkt.payload[..], &body[3 + usize::from(body[2])..], "{name}: payload");
            assert_eq!(usize::from(pkt.header.size), wire.len(), "{name}: size field");

            assert_eq!(seal(&pkt.header, &body), wire, "{name}: re-encryption differs from client");
        }
    }

    #[test]
    fn byte_by_byte_and_coalesced_input() {
        let (_, _, a) = golden::VECTORS[1];
        let (_, _, b) = golden::VECTORS[2];
        let stream: Vec<u8> = [hex(a), hex(b)].concat();
        let mut codec = any_seq();
        let mut buf = BytesMut::new();
        let mut got = Vec::new();
        for &byte in &stream {
            buf.put_u8(byte);
            while let Some(p) = codec.decode(&mut buf).unwrap() {
                got.push(p);
            }
        }
        assert_eq!(got.len(), 2);

        let mut codec = any_seq();
        let mut buf = BytesMut::from(&stream[..]);
        assert!(codec.decode(&mut buf).unwrap().is_some());
        assert!(codec.decode(&mut buf).unwrap().is_some());
        assert!(codec.decode(&mut buf).unwrap().is_none());
    }

    #[test]
    fn server_to_client_roundtrip_with_padding() {
        for mode in [Mode::Xor, Mode::Aes] {
            let mut server = WireCodec::new(SendPolicy { mode, flag: 2, random_padding: true });
            let mut client = WireCodec::new(SendPolicy::default());
            let mut wire = BytesMut::new();
            let mut pads = std::collections::BTreeSet::new();
            for i in 0..200u32 {
                let payload: Vec<u8> = (0..(i % 50)).map(|x| x as u8 ^ 0x5A).collect();
                server.encode(Outgoing::new(2, (i % 256) as u8, payload.clone()), &mut wire).unwrap();
                let p = client.decode(&mut wire).unwrap().unwrap();
                assert_eq!((p.main, p.sub, &p.payload[..]), (2, (i % 256) as u8, &payload[..]));
                assert_eq!(p.header.seq, i + 1, "seq starts at 1 and increments");
                assert_eq!(p.header.key, (i + 1) as u8, "key rolls like the client's");
                assert_eq!(Mode::from_byte(p.header.mode), Some(mode));
                pads.insert(p.pad);
            }
            assert_eq!(pads.len(), 8, "all pad counts 0..=7 used");
        }
    }

    fn frame(mode: u8, seq: u32, body: &[u8]) -> Vec<u8> {
        let h = Header { magic: MAGIC, size: (HEADER_LEN + body.len()) as u16, flag: 1, key: 4, mode, seq };
        seal(&h, body)
    }

    #[test]
    fn rejects_malformed_frames() {
        let dec = |bytes: &[u8]| WireCodec::new(SendPolicy::default()).decode(&mut BytesMut::from(bytes));

        let mut bad_magic = frame(1, 1, &[1, 5, 0]);
        bad_magic[0] = 0x34;
        assert!(matches!(dec(&bad_magic), Err(WireError::BadMagic(0x0034))));

        let mut tiny = frame(1, 1, &[1, 5, 0]);
        tiny[2] = 13;
        assert!(matches!(dec(&tiny), Err(WireError::Undersized(13))));

        let mut mode2 = frame(1, 1, &[1, 5, 0]);
        mode2[6] = 2;
        assert!(matches!(dec(&mode2), Err(WireError::UnknownMode(2))));

        assert!(matches!(dec(&frame(1, 1, &[1, 5, 8, 0, 0, 0, 0, 0, 0, 0, 0])), Err(WireError::BadPadding(8))));
        assert!(matches!(dec(&frame(3, 1, &[1, 5, 7, 0, 0])), Err(WireError::PaddingOverrun { pad: 7, body_len: 5 })));
    }

    #[test]
    fn oversized_header_fails_before_body_arrives() {
        let mut codec = WireCodec::new(SendPolicy::default()).with_max_frame(1024);
        let mut h = frame(1, 1, &[1, 5, 0]);
        h[2..4].copy_from_slice(&2000u16.to_le_bytes());
        let mut buf = BytesMut::from(&h[..HEADER_LEN]);
        assert!(matches!(codec.decode(&mut buf), Err(WireError::Oversized { size: 2000, max: 1024 })));
    }

    #[test]
    fn replay_and_downgrade_are_refused() {
        let mut codec = WireCodec::new(SendPolicy::default());
        let mut buf = BytesMut::from(&frame(1, 5, &[1, 5, 0])[..]);
        assert!(codec.decode(&mut buf).unwrap().is_some());
        buf.extend_from_slice(&frame(1, 5, &[1, 5, 0]));
        assert!(matches!(codec.decode(&mut buf), Err(WireError::Replay { seq: 5, last: 5 })));

        let mut codec = WireCodec::new(SendPolicy::default());
        let mut buf = BytesMut::from(&frame(0, 1, &[1, 5, 0])[..]);
        assert!(codec.decode(&mut buf).unwrap().is_some(), "plaintext accepted before encryption starts");
        buf.extend_from_slice(&frame(3, 2, &[1, 5, 0]));
        assert!(codec.decode(&mut buf).unwrap().is_some());
        buf.extend_from_slice(&frame(0, 3, &[1, 5, 0]));
        assert!(matches!(codec.decode(&mut buf), Err(WireError::PlaintextAfterEncrypted)));
    }

    #[test]
    fn oversized_payload_is_an_error_not_a_panic() {
        let mut codec = WireCodec::new(SendPolicy::default());
        let mut dst = BytesMut::new();
        let r = codec.encode(Outgoing::new(1, 1, vec![0u8; MAX_FRAME]), &mut dst);
        assert!(matches!(r, Err(WireError::Oversized { .. })));
        assert!(dst.is_empty());
    }
}
